%[text] # Exercise 3
%[text] Compare the original wide-area surveillance baseline against a new configuration that replaces the three stationary ground radars with the characterized radar from Exercise 2 while keeping the airborne radars and tracker configuration unchanged.
%[text] This live script adds the Exercise 2 output folder to the MATLAB path, updates the characterized `radarDataGenerator` to use sensor spherical detections, loads precomputed baseline results instead of rerunning the original simulation, and runs the updated configuration once to produce a compact comparison.
%%
%[text] ## Setup and Baseline Data
exercise2Path = "/MATLAB Drive/agenticaiaerospace/Exercise2/exercise2_output";
addpath(exercise2Path)
baselineFile = fullfile(tempdir,"exercise3_baseline_results.mat");
if ~isfile(baselineFile)
    error("Baseline data file not found: %s. Generate it once before running this live script.", baselineFile)
end
baselineData = load(baselineFile,"baselineResults");
baselineResults = baselineData.baselineResults;
viewerFigure = uifigure( ...
    Units="normalized", ...
    Position=[0.04 0.32 0.36 0.38], ...
    Name="Characterized Radar Tracking Viewer");
metricFigure = uifigure( ... %[output:239821d1]
    Units="normalized", ... %[output:239821d1]
    Position=[0.42 0.58 0.24 0.22], ... %[output:239821d1]
    Name="Live OSPA Metric Comparison"); %[output:239821d1]
metricLayout = uigridlayout(metricFigure,[1 1]); %[output:239821d1]
metricLayout.Padding = [10 8 10 8]; %[output:239821d1]
metricLayout.RowHeight = {'1x'};
metricLayout.ColumnWidth = {'1x'};
metricAxes = uiaxes(metricLayout); %[output:239821d1]
metricAxes.FontSize = 10; %[output:239821d1]
hold(metricAxes,"on") %[output:239821d1]
grid(metricAxes,"on") %[output:239821d1]
xlabel(metricAxes,"Scenario time (s)") %[output:239821d1]
ylabel(metricAxes,"OSPA") %[output:239821d1]
title(metricAxes,"Baseline vs Characterized Ground Radar") %[output:239821d1]
baselineLine = plot(metricAxes,baselineResults.Time,baselineResults.OSPA,LineWidth=1.5,Color=[0 0.4470 0.7410],DisplayName="Baseline"); %[output:239821d1]
characterizedLine = animatedline(metricAxes,LineWidth=1.5,Color=[0.8500 0.3250 0.0980],DisplayName="Characterized"); %[output:239821d1]
legend(metricAxes,"Location","northeast") %[output:239821d1]
xlim(metricAxes,[min(baselineResults.Time) max(baselineResults.Time)]) %[output:239821d1]
yMax = max(baselineResults.OSPA,[],'omitnan');
if isempty(yMax) || ~isfinite(yMax) || yMax <= 0
    yMax = 1;
end
ylim(metricAxes,[0 1.2*yMax]) %[output:239821d1]
%%
%[text] ## Configure the Characterized Ground Radar
run(fullfile(exercise2Path,"dataGenerator.m"))
characterizedGroundRadar = radar;
characterizedGroundRadar.DetectionCoordinates = "Sensor spherical";
characterizedGroundRadar.HasINS = true;
characterizedGroundRadar.SensorIndex = 1;
characterizedGroundRadar.ReferenceRCS = 10;
characterizedGroundRadar.RangeRateLimits = [-500 500];
characterizedGroundRadar.MountingAngles = [0 0 0];
characterizedGroundRadar.MountingLocation = [0 0 0];
disp(characterizedGroundRadar) %[output:3376e8de]
%%
%[text] ## Run the Updated Surveillance Configuration
scenario = helperCreateWideAreaSurveillanceScenario(characterizedGroundRadar);
characterizedResults = helperRunWideAreaSurveillanceTrackingWithComparison(scenario,characterizedGroundRadar,viewerFigure,metricAxes,characterizedLine,baselineResults);
%%
%[text] ## Summary Table
summaryTable = table( ...
    [mean(baselineResults.OSPA,"omitnan"); mean(characterizedResults.OSPA,"omitnan")], ...
    [median(baselineResults.OSPA,"omitnan"); median(characterizedResults.OSPA,"omitnan")], ...
    [max(baselineResults.OSPA,[],'omitnan'); max(characterizedResults.OSPA,[],'omitnan')], ...
    [numel(baselineResults.OSPA); numel(characterizedResults.OSPA)], ...
    'VariableNames', ["MeanOSPA" "MedianOSPA" "MaxOSPA" "NumUpdates"], ...
    'RowNames', ["Baseline" "CharacterizedGroundRadar"])
%%
%[text] ## Visualization Image
metricSnapshotFigure = figure(Position=[100 100 720 320]);
plot(baselineResults.Time,baselineResults.OSPA,LineWidth=1.5,Color=[0 0.4470 0.7410],DisplayName="Baseline")
hold on
plot(characterizedResults.Time,characterizedResults.OSPA,LineWidth=1.5,Color=[0.8500 0.3250 0.0980],DisplayName="Characterized")
grid on
xlabel("Scenario time (s)")
ylabel("OSPA")
title("OSPA Comparison for Baseline and Characterized Ground Radar")
legend(Location="northeast")
comparisonImageFile = fullfile(tempdir,"exercise3_characterized_ospa_comparison.png");
exportgraphics(gca,comparisonImageFile,Resolution=150)
imshow(comparisonImageFile)
axis off
close(comparisonFigure)
%%
%[text] ## Observations and Next Experiments
%[text] - The baseline is loaded from saved data and plotted in the default blue style while the updated configuration is streamed in orange-red during the new run.
%[text] - The characterized Exercise 2 radar is reused only for the three ground sites, and its detection coordinates are overridden to sensor spherical form for compatibility with the scenario and tracker.
%[text] - The airborne radars, scenario geometry, and tracker design remain unchanged so the comparison isolates the effect of the new ground-radar model.
%[text] - Recommended next experiments are to tune the characterized radar false-alarm rate, range-rate limits, and ambiguity settings and then compare OSPA, track continuity, and false-track counts. \

